    cols =len (grid [0 ])

    # Find the coordinates of the single non-zero pixel (color 4)
    r_idx ,c_idx =-1 ,-1 
    for r in range (rows ):
        for c in range (cols ):
            if grid [r ][c ]!=0 :
                r_idx ,c_idx =r ,c 
                break 
        if r_idx !=-1 :
            break 

            # Create a deep copy of the grid to modify
    new_grid =[row [:]for row in grid ]

    # Logic based on examples:
    # Ex 1: (2,0) -> Row 2 becomes all 4s (Horizontal expansion)
    # Ex 2: (5,4) -> Col 4 becomes all 4s (Vertical expansion)
    # Ex 3: (0,2) -> Col 2 becomes all 4s (Vertical expansion)
    # Observation: If the pixel is in the first column (c=0), it expands horizontally.
    # Otherwise, it expands vertically.

    if c_idx ==0 :
    # Expand horizontally across the row
        for c in range (cols ):
            new_grid [r_idx ][c ]=4 
